import React from 'react';

function EtablissementPage() {
  return (
    <div className="p-4">
      <h1 className="text-2xl font-bold text-green-500">Page des Établissements</h1>
      <p>Informations sur les différents établissements.</p>
    </div>
  );
}

export default EtablissementPage;
